/// One way of writing one instruction.
pub struct Form {
    pub name: &'static str,
    /// The two opcode words, high word first.
    pub opcode: u32,
    /// How many of those words the instruction really has, 1 or 2.
    pub words: u8,
    /// Operand kinds and places, in pairs.
    pub args: &'static str,
    /// The CPUs that have it, as [`feature`] bits.
    pub arch: u32,
}

const fn f(name: &'static str, opcode: u32, words: u8, args: &'static str, arch: u32) -> Form {
    Form {
        name,
        opcode,
        words,
        args,
        arch,
    }
}

