/// A form of [`CF_FORMS`].
pub struct CfForm {
    pub form: Form,
    /// Which bits of [`Form::opcode`] are fixed.
    pub mask: u32,
}

const fn cf(
    name: &'static str,
    opcode: u32,
    mask: u32,
    words: u8,
    args: &'static str,
    arch: u32,
) -> CfForm {
    CfForm {
        form: f(name, opcode, words, args, arch),
        mask,
    }
}

