/// `RAMBAR_ALT`, where it means `RAMBAR0`.
pub const RAMBAR: u16 = 97;
pub const RAMBAR_ALT: u16 = 65;

/// A CPU model: what it can assemble and which control registers
/// `movec` reaches on it.
pub struct CpuDef {
    pub name: &'static str,
    pub arch: u32,
    pub ctrl: &'static [u16],
}

const fn c(name: &'static str, arch: u32, ctrl: &'static [u16]) -> CpuDef {
    CpuDef { name, arch, ctrl }
}

